always_comb begin
  assert (count <= MAX_COUNT);
end

sequence req_then_ack;
  req ##[1:3] ack;
endsequence

reg f_past_valid = 1'b0;
always @(posedge clk) f_past_valid <= 1'b1;

always @(posedge clk)
  if (f_past_valid && !$past(rst))
    assert (count == $past(count) + $past(inc));

logic [3:0] outstanding;
always @(posedge clk)
  if (rst) outstanding <= '0;
  else outstanding <= outstanding + (req_fire) - (resp_fire);

(* anyconst *) logic [WIDTH-1:0] f_value;
logic f_tracking;
// set f_tracking when f_value is pushed;
// check the popped data equals f_value when it reaches the head

// In block A's proof
assume property (@(posedge clk) !(push && full));
// In block B's proof (B drives push)
assert property (@(posedge clk) !(push && full));

ref_impl  ref_i  (.clk, .rst, .in, .out(out_ref));
new_impl  new_i  (.clk, .rst, .in, .out(out_new));

always @(posedge clk)
  if (!rst) assert (out_ref == out_new);
